    void BuildPlanningUpgrade()
    {
        void Add(string page,string label,Action action){var bar=pages[page].Controls.OfType<FlowLayoutPanel>().First();bar.Controls.Add(Button(label,action));bar.WrapContents=true;bar.Height=Math.Max(bar.Height,92);}
        Add("Shopping List","Budget planner",ShowBudgetPlanner);Add("Watchlist","Priorities",ShowPriorities);Add("Trade Journal","Trade templates",ShowTemplates);Add("Selling Planner","What should I sell?",()=>{using var d=CreateSellView();d.ShowDialog(this);});Add("Price History","Variant charts",()=>ShowVariantChart(CurrentInventory()));Add("Market Health","Personal data check",()=>{using var d=CreateDataHealth();d.ShowDialog(this);});
        foreach(var (name,grid) in new[]{("Watchlist",dashboardWatch),("Deals",dashboardDeals),("FM",dashboardMarket)})dashboardSections[name]=grid.Parent!.Parent!;
        dashboardSections["Merchant"]=merchantDashboard.Parent!;
