    TradeDraft SaleDraft(SavedItem item)=>new(new(Guid.NewGuid().ToString(),item.Name,item.Variant,false,item.Quantity,1,0,DateTimeOffset.UtcNow){Profile=store.Profile},null,false,DateTimeOffset.UtcNow);
    void PrepareSale(SavedItem item)
    {if(File.Exists(DraftPath)){MessageBox.Show("Resume or discard the unfinished trade in Trade Journal first.");return;}var current=ItemIdentity.Resolve(store.Items(),ItemIdentity.Key(item));if(current is null||current.Quantity<=0){MessageBox.Show("This stack is no longer in inventory.");return;}using var d=CreateTradeEditor(null,false,SaleDraft(current));d.Text="Prepare sale • enter actual price, then confirm completed trade";d.ShowDialog(this);}
    void ConfigureSaleDrop(Control target)
    {target.AllowDrop=true;target.DragEnter+=(_,e)=>{if(e.Data?.GetData(typeof(string)) is string key&&ItemIdentity.Resolve(store.Items(),key) is {Quantity:>0})e.Effect=DragDropEffects.Move;};target.DragDrop+=(_,e)=>{if(e.Data?.GetData(typeof(string)) is string key&&ItemIdentity.Resolve(store.Items(),key) is {} item)BeginInvoke(()=>PrepareSale(item));};}
    Form CreateSellView()
    {
        var d=GridDialog("What should I sell? • estimates, not guaranteed proceeds",out var grid,out var bar);var order=new ComboBox(){DropDownStyle=ComboBoxStyle.DropDownList,Width=210};order.Items.AddRange(["Sell tags first","Highest supported value","Longest held","Lowest recorded cost"]);order.SelectedIndex=0;bar.Controls.Add(order);var keep=new CheckBox(){Text="Include Keep-tagged items",Width=215,Height=35};bar.Controls.Add(keep);
        void RenderSell(){SetColumns(grid,["Item / variant","Owned","Tag","Supported stack value","Recorded remaining cost","Oldest remaining purchase","Evidence"]);var rows=store.Items().Where(i=>i.Quantity>0).Select(i=>{var basis=PlanningTools.Basis(i,features.Trades.Where(t=>t.Profile==store.Profile));var target=EligibleObservations().Where(o=>TextKey.Search(o.Name)==TextKey.Search(i.Name)&&(!o.Equipment||o.VariantComplete&&o.Variant==i.Variant)).OrderByDescending(o=>o.RetrievedAt).FirstOrDefault();var value=target is null?null:ValuationEngine.Estimate(EligibleObservations(),target,DateTimeOffset.UtcNow,TimeSpan.FromHours(settings.FreshHours),settings.Discount);if(value?.Confidence<50)value=null;string tag=features.Memos.FirstOrDefault(m=>m.Profile==store.Profile&&TextKey.Search(m.Name)==TextKey.Search(i.Name))?.Tag??"";return new{item=i,basis,value,tag};}).Where(r=>keep.Checked||r.tag!="Keep").ToList();var sorted=order.SelectedIndex switch{1=>rows.OrderByDescending(r=>r.value?.Value*r.item.Quantity),2=>rows.OrderBy(r=>r.basis.Oldest??DateTimeOffset.MaxValue),3=>rows.OrderBy(r=>r.basis.Cost??decimal.MaxValue),_=>rows.OrderBy(r=>r.tag=="Sell"?0:1).ThenByDescending(r=>r.value?.Value*r.item.Quantity)};foreach(var r in sorted){int n=grid.Rows.Add(r.item.Name+" • "+r.item.Variant,r.item.Quantity,r.tag,TextKey.Mesos(r.value?.Value*r.item.Quantity),r.basis.Cost is null?"Unknown / journal-stock mismatch":TextKey.Mesos(r.basis.Cost),r.basis.Oldest?.LocalDateTime.ToString("d")??"Unknown",r.value is null?"Insufficient comparable evidence":$"{r.value.Confidence}/100 • {r.value.Basis}; fees excluded");grid.Rows[n].Tag=r.item;}grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;}
        bar.Controls.Add(Button("Inspect item",()=>{if(SelectedMerchant(grid) is SavedItem i)ShowItemDetails(i);}));bar.Controls.Add(Button("Prepare sale",()=>{if(SelectedMerchant(grid) is SavedItem i)PrepareSale(i);}));order.SelectedIndexChanged+=(_,_)=>RenderSell();keep.CheckedChanged+=(_,_)=>RenderSell();d.Activated+=(_,_)=>RenderSell();RenderSell();return d;
    }
    Form CreateBudgetPlanner()
    {
        var d=GridDialog("Shopping budget • current character",out var grid,out var bar);var budget=Amount(Planning.Budgets.GetValueOrDefault(store.Profile));budget.Width=170;bar.Controls.Add(new Label(){Text="Spending limit",AutoSize=true,Padding=new Padding(5,9,0,0)});bar.Controls.Add(budget);var total=new Label(){Dock=DockStyle.Bottom,Height=115,Padding=new Padding(12),BackColor=Surface};d.Controls.Add(total);grid.BringToFront();
        void Update(){decimal known=0;int missing=0;SetColumns(grid,["Item / variant","Still needed","Current ask-based estimate","Item budget ceiling"]);foreach(var s in Workspace.Shopping.Where(s=>s.Profile==store.Profile&&s.Quantity>s.Purchased)){var cost=WorkspaceOptions.ShoppingCost(s,EligibleObservations(),DateTimeOffset.UtcNow,settings.FreshHours);if(cost is null)missing++;else known+=cost.Value;grid.Rows.Add(s.Name+" • "+s.Variant,s.Quantity-s.Purchased,TextKey.Mesos(cost),s.Budget==0?"Not set":TextKey.Mesos(s.Budget));}var balance=store.Characters().Single(c=>c.Id==store.Profile).Mesos;var available=Math.Min(balance,budget.Value);total.Text=$"Recorded balance: {TextKey.Mesos(balance)} • Spending limit: {TextKey.Mesos(budget.Value)}\nKnown planned subtotal: {TextKey.Mesos(known)} • {missing} entries unpriced • fees excluded\n"+(known>available?$"Known costs already exceed available budget by {TextKey.Mesos(known-available)}.":missing>0?"Total affordability is unknown until every item is priced.":$"Estimated remaining within both limits: {TextKey.Mesos(available-known)}.")+"\nThis is a plan; it does not reserve mesos or change inventory.";}
        bar.Controls.Add(Button("Save limit",()=>{Planning.Budgets[store.Profile]=budget.Value;SaveFeatures();Update();}));budget.ValueChanged+=(_,_)=>Update();Update();return d;
    }
    void ShowBudgetPlanner(){using var d=CreateBudgetPlanner();d.ShowDialog(this);}
    void ShowPriorities(){using var d=CreatePriorities();d.ShowDialog(this);}
    Form CreatePriorities()
    {
        var d=GridDialog("Watchlist priorities • thresholds are asking prices",out var grid,out var bar);
        void Refresh(){SetColumns(grid,["Item / exact variant","Priority","Threshold","Meaning"]);foreach(var i in store.Items().Where(i=>i.Watch)){var p=Planning.Priorities.FirstOrDefault(p=>p.Profile==store.Profile&&ItemIdentity.Key(p.Name,p.Variant)==ItemIdentity.Key(i));int n=grid.Rows.Add(i.Name+" • "+i.Variant,p?.Group??"Unassigned",p is null||p.Threshold==0?"Off":TextKey.Mesos(p.Threshold),p?.Group=="Sell soon"?"Notify when an ask is at/above target; not a buyer offer":p?.Group=="Buy soon"?"Notify when an ask is at/below target":"No priority alert; other alert settings remain separate");grid.Rows[n].Tag=i;}grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;}
        bar.Controls.Add(Button("Set selected priority",()=>{if(SelectedMerchant(grid) is not SavedItem item)return;using var edit=EntryDialog("Priority • "+item.Name,out var f);var old=Planning.Priorities.FirstOrDefault(p=>p.Profile==store.Profile&&ItemIdentity.Key(p.Name,p.Variant)==ItemIdentity.Key(item));var group=new ComboBox(){DropDownStyle=ComboBoxStyle.DropDownList};group.Items.AddRange(["Buy soon","Sell soon","Just tracking"]);group.SelectedItem=old?.Group??"Just tracking";var threshold=Amount(old?.Threshold??0);Field(f,"Group",group);Field(f,"Unit asking-price threshold (0 disables priority alerts)",threshold);f.Controls.Add(Button("Save priority",()=>{if(old is not null)Planning.Priorities.Remove(old);Planning.Priorities.Add(new(store.Profile,item.Name,item.Variant,group.Text,threshold.Value));SaveFeatures();edit.Close();Refresh();}));edit.ShowDialog(d);}));Refresh();return d;
    }
    bool PriorityStillEligible(InboxEntry entry)
    {if(!entry.Key.StartsWith("priority:"))return true;return Planning.Priorities.Any(p=>p.Profile==store.Profile&&store.Items().Any(i=>i.Watch&&!i.Muted&&ItemIdentity.Key(i)==ItemIdentity.Key(p.Name,p.Variant))&&EligibleObservations().Any(o=>PlanningTools.PriorityMatches(p,o,DateTimeOffset.UtcNow,settings.FreshHours)&&entry.Key=="priority:"+p.Group+":"+p.Threshold+":"+o.Key+":"+o.UnitPrice));}
    void CheckPriorityAlerts()
    {
        foreach(var p in Planning.Priorities.Where(p=>p.Profile==store.Profile)){var item=store.Items().FirstOrDefault(i=>ItemIdentity.Key(i)==ItemIdentity.Key(p.Name,p.Variant));if(item is not {Watch:true,Muted:false})continue;var row=EligibleObservations().Where(o=>PlanningTools.PriorityMatches(p,o,DateTimeOffset.UtcNow,settings.FreshHours)).OrderBy(o=>p.Group=="Buy soon"?o.UnitPrice:-o.UnitPrice).FirstOrDefault();if(row is null)continue;AddInbox("priority:"+p.Group+":"+p.Threshold+":"+row.Key+":"+row.UnitPrice,p.Name+" • "+p.Group,$"Asking price {TextKey.Mesos(row.UnitPrice)} meets your priority threshold. This is not a completed sale or buyer offer.",row.Url,row);}
    }
    void SaveTemplate(TradeEntry entry)
    {using var d=EntryDialog("Save reusable trade template",out var f);var label=new TextBox(){Text=entry.Name+(entry.Buy?" purchase":" sale"),MaxLength=250};Field(f,"Template name",label);f.Controls.Add(Button("Save template",()=>{try{new CompanionFeatures{Trades=[entry]}.Validate();if(string.IsNullOrWhiteSpace(label.Text))throw new FormatException("Enter a template name");Planning.Templates.Add(new(Guid.NewGuid().ToString(),entry.Profile,label.Text.Trim(),entry.Name,entry.Variant,entry.Buy,entry.Quantity,entry.UnitPrice,entry.Fees));SaveFeatures();d.Close();}catch(Exception e){MessageBox.Show(e.Message);}}));d.ShowDialog(this);}
