    void ShowVariantChart(SavedItem? item){using var d=CreateVariantChart(item);d.ShowDialog(this);}
    Form CreateVariantChart(SavedItem? item)
    {
        var d=GridDialog("Exact-variant price history",out var grid,out var bar);var name=new TextBox(){Text=item?.Name??search.Text,Width=200};var variant=new ComboBox(){Width=250,DropDownStyle=ComboBoxStyle.DropDownList};var mode=new ComboBox(){Width=215,DropDownStyle=ComboBoxStyle.DropDownList};mode.Items.AddRange(["Market asking prices","My recorded sales"]);mode.SelectedIndex=0;bar.Controls.Add(name);bar.Controls.Add(variant);bar.Controls.Add(mode);var chart=new HistoryPlot(){Dock=DockStyle.Bottom,Height=260};d.Controls.Add(chart);grid.BringToFront();
        void Plot(){SetColumns(grid,["Source time","Unit price","Evidence","Exact variant"]);string v=variant.SelectedItem as string??"";List<Observation> points;if(mode.SelectedIndex==0)points=PlanningTools.VariantHistory(store.History().Where(o=>settings.Sources.Any(s=>s.Id==o.Provider&&s.Authorized)),name.Text,v);else points=features.Trades.Where(t=>t.Profile==store.Profile&&!t.Buy&&TextKey.Search(t.Name)==TextKey.Search(name.Text)&&t.Variant==v).Select(t=>new Observation{Name=t.Name,Variant=t.Variant,ObservedAt=t.At,RetrievedAt=t.At,UnitPrice=t.UnitPrice,Kind=EvidenceKind.ReportedSale,Provider="Personal journal",ListingId=t.Id}).ToList();chart.Points=points;chart.Invalidate();foreach(var p in points.OrderByDescending(o=>o.ObservedAt))grid.Rows.Add(p.ObservedAt?.LocalDateTime.ToString("g")??"Unknown",TextKey.Mesos(p.UnitPrice),mode.SelectedIndex==0?"Asking • not a completed sale":"Your recorded sale • unverified",p.Variant);}
        void Variants(){var previous=variant.SelectedItem as string??item?.Variant??"";variant.Items.Clear();var values=store.History().Where(o=>TextKey.Search(o.Name)==TextKey.Search(name.Text)).Select(o=>o.Variant).Concat(features.Trades.Where(t=>t.Profile==store.Profile&&TextKey.Search(t.Name)==TextKey.Search(name.Text)).Select(t=>t.Variant)).Concat(store.Items().Where(i=>TextKey.Search(i.Name)==TextKey.Search(name.Text)).Select(i=>i.Variant)).Append("").Distinct().Order().ToArray();variant.Items.AddRange(values);variant.SelectedItem=values.Contains(previous)?previous:"";Plot();}name.TextChanged+=(_,_)=>Variants();variant.SelectedIndexChanged+=(_,_)=>Plot();mode.SelectedIndexChanged+=(_,_)=>Plot();Variants();return d;
    }
    sealed record HealthFinding(string Page,SavedItem? Item,string Issue,string Action);
    Form CreateDataHealth()
    {
        var d=GridDialog("Personal data health • review before changing records",out var grid,out var bar);
        void Reload(){SetColumns(grid,["Item / section","Finding","Review action"]);void Add(string name,HealthFinding f){int n=grid.Rows.Add(name,f.Issue,f.Action);grid.Rows[n].Tag=f;}foreach(var i in store.Items().Where(i=>i.Quantity>0)){if(InventoryCategory(i)=="EQUIP"&&(i.Variant.Length==0||!observations.Any(o=>TextKey.Search(o.Name)==TextKey.Search(i.Name)&&o.Variant==i.Variant&&o.VariantComplete)))Add(i.Name,new("Inventory",i,"Equipment variant is missing or has no complete matching market record","Review saved stats; do not guess missing values"));var basis=PlanningTools.Basis(i,features.Trades.Where(t=>t.Profile==store.Profile));if(basis.Cost is null)Add(i.Name,new("Trade Journal",i,$"Cost unknown: stock {i.Quantity}, journal remainder {basis.JournalUnits}","Review purchase records and stock"));if(!EligibleObservations().Any(o=>TextKey.Search(o.Name)==TextKey.Search(i.Name)&&(!o.Equipment||o.Variant==i.Variant)&&o.Fresh(DateTimeOffset.UtcNow,TimeSpan.FromHours(settings.FreshHours))&&o.RetrievedAt>=DateTimeOffset.UtcNow.AddMinutes(-30)))Add(i.Name,new("Price Checker",i,"No recently checked matching price evidence","Search source or keep value unknown"));}foreach(var group in Workspace.Shopping.Where(s=>s.Profile==store.Profile).GroupBy(s=>ItemIdentity.Key(s.Name,s.Variant)).Where(g=>g.Count()>1))Add(group.First().Name,new("Duplicate Review",null,"Overlapping shopping entries","Review duplicates; nothing is deleted"));var journal=features.Trades.Where(t=>t.Profile==store.Profile).ToList();foreach(var group in journal.GroupBy(t=>new{t.Name,t.Variant,t.Buy,t.Quantity,t.UnitPrice,t.Fees})){var entries=group.OrderBy(t=>t.At).ToList();for(int j=1;j<entries.Count;j++)if(PolishTools.Duplicate(entries[j-1],entries[j]))Add(entries[j].Name,new("Duplicate Review",null,"Possible repeated trade within five minutes","Review both records; neither is removed"));}foreach(var outcome in CompanionFeatures.Outcomes(features.Trades.Where(t=>t.Profile==store.Profile)).Where(o=>o.UnmatchedUnits>0))Add(features.Trades.First(t=>t.Id==outcome.Id).Name,new("Trade Journal",null,$"{outcome.UnmatchedUnits} sold units lack recorded purchase cost","Review journal"));grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;}
        bar.Controls.Add(Button("Review selected",()=>{if(SelectedMerchant(grid) is not HealthFinding f)return;if(f.Page=="Inventory"&&f.Item is {} i)EditItem(i,false);else{if(f.Item is {} item)search.Text=item.Name;ShowPage(f.Page);d.Close();}Reload();}));bar.Controls.Add(Button("Recheck",Reload));Reload();return d;
    }
    void ApplyDashboardPanels()
    {
        if(!planningReady)return;foreach(var (name,control) in dashboardSections)control.Visible=Planning.DashboardPanels.Contains(name);var upper=dashboardSections["Watchlist"].Parent as TableLayoutPanel;if(upper is not null){bool a=Planning.DashboardPanels.Contains("Watchlist"),b=Planning.DashboardPanels.Contains("Deals");upper.ColumnStyles[0].Width=a?(b?50:100):0;upper.ColumnStyles[1].Width=b?(a?50:100):0;var layout=(TableLayoutPanel)upper.Parent!;layout.RowStyles[3].SizeType=SizeType.Percent;layout.RowStyles[3].Height=a||b?50:0;layout.RowStyles[4].SizeType=SizeType.Percent;layout.RowStyles[4].Height=Planning.DashboardPanels.Contains("FM")?50:0;}
    }
